import React, { useEffect, useMemo, useRef, useState } from "react";
import { AccessibilityInfo, PanResponder, View, type ViewStyle } from "react-native";
import {
  BlurStyle,
  Canvas,
  Group,
  Picture,
  PointMode,
  Skia,
  StrokeCap,
  TileMode,
  vec,
  type SkCanvas,
  type SkPicture,
} from "@shopify/react-native-skia";
import {
  allSettled,
  createWorld,
  diceValues,
  grabDice,
  moveHeld,
  releaseDice,
  stepDice,
  throwDice,
  type DiceWorld,
} from "./diceMath";
import { TRAY_H, TRAY_W, buildFrame, staticScene, unproject, type Item } from "./diceDesign";

export type DiceTrayProps = {
  /** How many dice, 1 to 3. */
  count?: 1 | 2 | 3;
  /** Width in layout points; the tray keeps its 340 x 460 proportions. */
  width?: number;
  slowMotion?: boolean;
  reducedMotion?: boolean;
  /** Increment to throw the dice for the user. */
  rollTick?: number;
  /** Called once every die has come to rest, with the face values. */
  onSettled?: (values: number[]) => void;
  /** Hook haptics here: 'pickup', 'throw', 'impact' (felt or rail hit, strength 0 to 1) and 'settle'. */
  onFeedback?: (event: "pickup" | "throw" | "impact" | "settle", strength?: number) => void;
  label?: string;
  style?: ViewStyle;
};

const TRAY_HALF_X = 3.4;
const TRAY_HALF_Z = 4.4;

function safeDispose(o: unknown): void {
  const d = (o as { dispose?: () => void } | null | undefined)?.dispose;
  if (typeof d === "function") {
    try {
      d.call(o);
    } catch {
      /* some hosts free these on their own */
    }
  }
}

/** Paint a draw list with Skia. */
function paintItems(canvas: SkCanvas, items: Item[]) {
  const paint = Skia.Paint();
  paint.setAntiAlias(true);
  const blurs = new Map<number, ReturnType<typeof Skia.MaskFilter.MakeBlur>>();
  for (const it of items) {
    if (it.k === "poly") {
      const path = Skia.Path.Make();
      path.moveTo(it.pts[0], it.pts[1]);
      for (let i = 2; i < it.pts.length; i += 2) path.lineTo(it.pts[i], it.pts[i + 1]);
      path.close();
      paint.setShader(null);
      paint.setMaskFilter(null);
      paint.setColor(Skia.Color(it.color));
      let shader: ReturnType<typeof Skia.Shader.MakeLinearGradient> | null = null;
      if (it.grad) {
        shader = Skia.Shader.MakeLinearGradient(
          vec(it.grad.x0, it.grad.y0),
          vec(it.grad.x1, it.grad.y1),
          [Skia.Color(it.grad.c0), Skia.Color(it.grad.c1)],
          null,
          TileMode.Clamp,
        );
        paint.setShader(shader);
      }
      if (it.blur) {
        const key = Math.round(it.blur * 10);
        let f = blurs.get(key);
        if (!f) {
          f = Skia.MaskFilter.MakeBlur(BlurStyle.Normal, it.blur / 2, true);
          blurs.set(key, f);
        }
        paint.setMaskFilter(f);
      }
      paint.setAlphaf(it.alpha ?? 1);
      canvas.drawPath(path, paint);
      path.dispose?.();
      paint.setShader(null);
      safeDispose(shader);
    } else if (it.k === "dots") {
      paint.setShader(null);
      paint.setMaskFilter(null);
      paint.setColor(Skia.Color(it.color));
      paint.setAlphaf(it.alpha);
      paint.setStrokeWidth(it.size);
      paint.setStrokeCap(StrokeCap.Square);
      const pts = [];
      for (let i = 0; i < it.pts.length; i += 2) pts.push(vec(it.pts[i], it.pts[i + 1]));
      canvas.drawPoints(PointMode.Points, pts, paint);
    } else {
      paint.setShader(null);
      paint.setMaskFilter(null);
      paint.setColor(Skia.Color(it.color));
      paint.setAlphaf(it.alpha ?? 1);
      paint.setStrokeWidth(it.width);
      paint.setStrokeCap(StrokeCap.Round);
      canvas.drawLine(it.pts[0], it.pts[1], it.pts[2], it.pts[3], paint);
    }
  }
  blurs.forEach((f) => safeDispose(f));
  safeDispose(paint);
}

function record(items: Item[]): SkPicture {
  const rec = Skia.PictureRecorder();
  const canvas = rec.beginRecording(Skia.XYWHRect(0, 0, TRAY_W, TRAY_H));
  paintItems(canvas, items);
  return rec.finishRecordingAsPicture();
}

export function DiceTray({
  count = 2,
  width = TRAY_W,
  slowMotion = false,
  reducedMotion,
  rollTick = 0,
  onSettled,
  onFeedback,
  label = "A felt dice tray. Drag to pick up the dice, flick to throw them. They tumble, bounce off the rails and settle on a face",
  style,
}: DiceTrayProps) {
  const scale = width / TRAY_W;
  const height = TRAY_H * scale;
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const worldRef = useRef<DiceWorld | null>(null);
  if (!worldRef.current) worldRef.current = createWorld(count, TRAY_HALF_X, TRAY_HALF_Z, 11);
  const latest = useRef({ slowMotion, reduce, onSettled, onFeedback });
  latest.current = { slowMotion, reduce, onSettled, onFeedback };
  const statics = useMemo(() => staticScene(TRAY_HALF_X, TRAY_HALF_Z), []);
  const [still, setStill] = useState<{ back: SkPicture; front: SkPicture } | null>(null);
  const [frame, setFrame] = useState<SkPicture | null>(null);
  const hand = useRef({ active: false, x: 0, y: 0, moved: 0, startX: 0, startY: 0 });
  const rollSeen = useRef(rollTick);
  const wasSettled = useRef(true);
  const pending = useRef<"roll" | null>(null);
  const seq = useRef(1);

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => {
        if (alive) setSystemReduce(v);
      })
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);

  // The felt and rails never change: record them once.
  useEffect(() => {
    const back = record(statics.back);
    const front = record(statics.front);
    setStill({ back, front });
    return () => {
      setTimeout(() => {
        safeDispose(back);
        safeDispose(front);
      }, 1500);
    };
  }, [statics]);

  // A new count rebuilds the dice, flat on the felt.
  useEffect(() => {
    worldRef.current = createWorld(count, TRAY_HALF_X, TRAY_HALF_Z, 11);
    wasSettled.current = true;
  }, [count]);

  useEffect(() => {
    if (rollTick !== rollSeen.current) {
      rollSeen.current = rollTick;
      pending.current = "roll";
    }
  }, [rollTick]);

  // JS-thread frame loop: step the rigid bodies, then record one picture of shadows and dice.
  useEffect(() => {
    let alive = true;
    let last = 0;
    let prev: SkPicture | null = null;
    const retired: unknown[] = [];
    const startRoll = (w: DiceWorld) => {
      seq.current += 1;
      throwDice(w, [(Math.sin(seq.current * 1.7)) * 1.2, 2.4, TRAY_HALF_Z * 0.78], [Math.sin(seq.current * 2.9) * 3.2, 4, -(21 + (seq.current % 4) * 2)], 1, seq.current * 7919);
      wasSettled.current = false;
      latest.current.onFeedback?.("throw", 0.8);
    };
    const loop = (now: number) => {
      if (!alive) return;
      const w = worldRef.current!;
      const dt = last ? Math.min(0.5, (now - last) / 1000) : 1 / 60;
      last = now;
      if (pending.current === "roll") {
        pending.current = null;
        startRoll(w);
        if (latest.current.reduce) {
          // Reduce Motion: no tumbling to watch, show the settled throw.
          let t = 0;
          while (t < 12 && !allSettled(w)) {
            stepDice(w, 1 / 60);
            t += 1 / 60;
          }
        }
      }
      const anyHeld = w.dice.some((d) => d.held);
      if (anyHeld) {
        const h = hand.current;
        const target = unproject(h.x, h.y, 2.3);
        moveHeld(w, target, Math.min(dt, 0.05));
      }
      if (!latest.current.reduce) {
        stepDice(w, Math.min(dt, 0.1) * (latest.current.slowMotion ? 0.25 : 1));
      }
      if (w.impact > 2.5) latest.current.onFeedback?.("impact", Math.min(1, w.impact / 14));
      w.impact = 0;
      if (!wasSettled.current && !anyHeld && allSettled(w)) {
        wasSettled.current = true;
        latest.current.onFeedback?.("settle", 0.5);
        latest.current.onSettled?.(diceValues(w));
      }
      const f = buildFrame(w);
      const pic = record([...f.shadows, ...f.dice]);
      setFrame(pic);
      if (prev) retired.push(prev);
      while (retired.length > 8) safeDispose(retired.shift());
      prev = pic;
      requestAnimationFrame(loop);
    };
    const raf = requestAnimationFrame(loop);
    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      const rest = [...retired, prev];
      setTimeout(() => rest.forEach(safeDispose), 1500);
    };
  }, []);

  const pan = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => !latest.current.reduce,
        onPanResponderGrant: (evt) => {
          const x = evt.nativeEvent.locationX / scale, y = evt.nativeEvent.locationY / scale;
          hand.current = { active: true, x, y, moved: 0, startX: x, startY: y };
          const w = worldRef.current!;
          seq.current += 1;
          grabDice(w, seq.current * 31);
          wasSettled.current = false;
          latest.current.onFeedback?.("pickup", 0.4);
        },
        onPanResponderMove: (evt) => {
          const h = hand.current;
          h.x = evt.nativeEvent.locationX / scale;
          h.y = evt.nativeEvent.locationY / scale;
          h.moved = Math.max(h.moved, Math.hypot(h.x - h.startX, h.y - h.startY));
        },
        onPanResponderRelease: () => {
          const w = worldRef.current!;
          const h = hand.current;
          h.active = false;
          const speed = releaseDice(w, seq.current * 17);
          // A plain tap drops the dice where they are; a flick throws them.
          latest.current.onFeedback?.("throw", Math.min(1, speed / 30));
        },
        onPanResponderTerminate: () => {
          const w = worldRef.current!;
          hand.current.active = false;
          releaseDice(w, seq.current * 17);
        },
        onPanResponderTerminationRequest: () => false,
      }),
    [scale],
  );

  return (
    <View
      style={[{ width, height, borderRadius: 18, overflow: "hidden", backgroundColor: "#1a120d" }, style]}
      accessibilityLabel={label}
      accessibilityRole="image"
      {...pan.panHandlers}
    >
      <Canvas pointerEvents="none" style={{ width, height }}>
        <Group transform={[{ scale }]}>
          {still ? <Picture picture={still.back} /> : null}
          {frame ? <Picture picture={frame} /> : null}
          {still ? <Picture picture={still.front} /> : null}
        </Group>
      </Canvas>
    </View>
  );
}

/* Rigid-body dice on a felt tray. Pure TypeScript, no dependencies, shared by
   the React Native component, the web preview and the tests.

   Units: one die edge = 1. y is up, the felt is y = 0. Each die is a unit-mass
   cube (isotropic inertia I = m a^2 / 6). Contacts are the eight corners against
   the felt and the rail walls, and corners against the other dice, resolved with
   sequential impulses (restitution, Coulomb friction, rolling resistance) on a
   fixed 1/360 s step. */

export type V3 = [number, number, number];
export type Q4 = [number, number, number, number]; // w, x, y, z

export type Die = {
  p: V3;
  q: Q4;
  v: V3;
  w: V3;
  rest: number; // seconds spent nearly still
  asleep: boolean;
  held: boolean;
};

export type DiceWorld = {
  dice: Die[];
  halfX: number;
  halfZ: number;
  clock: number;
  seed: number;
  settledFor: number;
  /** Hardest felt or rail hit since the host last read and cleared it (normal impulse, for haptics). */
  impact: number;
};

export type DiceOptions = {
  gravity: number;
  floorRestitution: number;
  wallRestitution: number;
  floorFriction: number;
  wallFriction: number;
  dieFriction: number;
  dieRestitution: number;
  rolling: number;
};

export const DICE_DEFAULTS: DiceOptions = {
  gravity: 95,
  floorRestitution: 0.34,
  wallRestitution: 0.5,
  floorFriction: 0.5,
  wallFriction: 0.3,
  dieFriction: 0.4,
  dieRestitution: 0.4,
  rolling: 0.9,
};

export const STEP = 1 / 360;
const SKIN = 0.02; // contact skin so exactly-touching faces still register
const INV_I = 6; // 1 / (m a^2 / 6) with m = a = 1

/* Face values: local +y 1, -y 6, +x 3, -x 4, +z 2, -z 5 (opposites add to 7). */
export const FACE_AXES: { axis: 0 | 1 | 2; sign: 1 | -1; value: number }[] = [
  { axis: 1, sign: 1, value: 1 },
  { axis: 1, sign: -1, value: 6 },
  { axis: 0, sign: 1, value: 3 },
  { axis: 0, sign: -1, value: 4 },
  { axis: 2, sign: 1, value: 2 },
  { axis: 2, sign: -1, value: 5 },
];

export function mulberry(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function qMul(a: Q4, b: Q4): Q4 {
  return [
    a[0] * b[0] - a[1] * b[1] - a[2] * b[2] - a[3] * b[3],
    a[0] * b[1] + a[1] * b[0] + a[2] * b[3] - a[3] * b[2],
    a[0] * b[2] - a[1] * b[3] + a[2] * b[0] + a[3] * b[1],
    a[0] * b[3] + a[1] * b[2] - a[2] * b[1] + a[3] * b[0],
  ];
}

export function qNorm(q: Q4): Q4 {
  const l = Math.hypot(q[0], q[1], q[2], q[3]) || 1;
  return [q[0] / l, q[1] / l, q[2] / l, q[3] / l];
}

export function qAxisAngle(axis: V3, angle: number): Q4 {
  const l = Math.hypot(axis[0], axis[1], axis[2]) || 1;
  const s = Math.sin(angle / 2) / l;
  return [Math.cos(angle / 2), axis[0] * s, axis[1] * s, axis[2] * s];
}

/** Row-major 3x3 rotation matrix of a unit quaternion. */
export function qMat(q: Q4): number[] {
  const [w, x, y, z] = q;
  return [
    1 - 2 * (y * y + z * z), 2 * (x * y - w * z), 2 * (x * z + w * y),
    2 * (x * y + w * z), 1 - 2 * (x * x + z * z), 2 * (y * z - w * x),
    2 * (x * z - w * y), 2 * (y * z + w * x), 1 - 2 * (x * x + y * y),
  ];
}

const cross = (a: V3, b: V3): V3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const dot = (a: V3, b: V3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

export const CORNERS: V3[] = [];
for (let i = 0; i < 8; i++) CORNERS.push([i & 1 ? 0.5 : -0.5, i & 2 ? 0.5 : -0.5, i & 4 ? 0.5 : -0.5]);

function mulMat(m: number[], v: V3): V3 {
  return [m[0] * v[0] + m[1] * v[1] + m[2] * v[2], m[3] * v[0] + m[4] * v[1] + m[5] * v[2], m[6] * v[0] + m[7] * v[1] + m[8] * v[2]];
}

export function cornerOffsets(m: number[]): V3[] {
  return CORNERS.map((c) => mulMat(m, c));
}

export function createDie(p: V3, q: Q4 = [1, 0, 0, 0]): Die {
  return { p: [...p] as V3, q, v: [0, 0, 0], w: [0, 0, 0], rest: 0, asleep: false, held: false };
}

export function createWorld(count: number, halfX = 3.4, halfZ = 4.4, seed = 1): DiceWorld {
  const dice: Die[] = [];
  const rng = mulberry(seed);
  for (let i = 0; i < count; i++) {
    const a = rng() * 6.283;
    const q = qNorm([rng() - 0.5, rng() - 0.5, rng() - 0.5, rng() - 0.5]);
    const d = createDie([(i - (count - 1) / 2) * 1.5, 0.5, halfZ * 0.35 + (rng() - 0.5) * 0.4], q);
    // Start flat: snap to a random face up.
    d.q = qAxisAngle([0, 1, 0], a);
    dice.push(d);
  }
  return { dice, halfX, halfZ, clock: 0, seed, settledFor: 0, impact: 0 };
}

/** Throw every die from a hand position with a given launch velocity. */
export function throwDice(world: DiceWorld, from: V3, vel: V3, spinScale = 1, seed?: number) {
  const rng = mulberry(seed ?? (world.seed = (world.seed * 1664525 + 1013904223) >>> 0));
  world.dice.forEach((d, i) => {
    const off = (i - (world.dice.length - 1) / 2) * 0.95;
    d.p = [from[0] + off, from[1] + (rng() - 0.5) * 0.3, from[2] + (rng() - 0.5) * 0.6];
    d.q = qNorm([rng() - 0.5, rng() - 0.5, rng() - 0.5, rng() - 0.5]);
    const jitter = 0.85 + rng() * 0.3;
    d.v = [vel[0] * jitter + (rng() - 0.5) * 1.6, vel[1], vel[2] * jitter + (rng() - 0.5) * 1.6];
    const sp = (14 + rng() * 16) * spinScale;
    const ax: V3 = [rng() - 0.5, rng() - 0.5, rng() - 0.5];
    const l = Math.hypot(ax[0], ax[1], ax[2]) || 1;
    // Spin about an axis roughly across the throw, like a real wrist flick.
    d.w = [(ax[0] / l) * sp + vel[2] * 0.5, (ax[1] / l) * sp * 0.4, (ax[2] / l) * sp - vel[0] * 0.5];
    d.rest = 0;
    d.asleep = false;
    d.held = false;
  });
  world.settledFor = 0;
}

type Body = Die;

function pointVel(b: Body, r: V3): V3 {
  const c = cross(b.w, r);
  return [b.v[0] + c[0], b.v[1] + c[1], b.v[2] + c[2]];
}

function angularTerm(r: V3, n: V3): number {
  const rn = cross(r, n);
  const c = cross([rn[0] * INV_I, rn[1] * INV_I, rn[2] * INV_I], r);
  return dot(n, c);
}

function applyImpulse(b: Body, r: V3, j: V3) {
  b.v[0] += j[0];
  b.v[1] += j[1];
  b.v[2] += j[2];
  const t = cross(r, j);
  b.w[0] += t[0] * INV_I;
  b.w[1] += t[1] * INV_I;
  b.w[2] += t[2] * INV_I;
}

/** One contact between body A (at offset rA) and optionally body B. n points from B (or the wall) toward A. */
function resolveContact(
  A: Body, rA: V3, B: Body | null, rB: V3 | null, n: V3, restitution: number, mu: number, approach: number,
) {
  const uA = pointVel(A, rA);
  const uB = B && rB ? pointVel(B, rB) : ([0, 0, 0] as V3);
  const u: V3 = [uA[0] - uB[0], uA[1] - uB[1], uA[2] - uB[2]];
  const un = dot(u, n);
  if (un >= 0) return 0;
  let denom = 1 + angularTerm(rA, n);
  if (B && rB) denom += 1 + angularTerm(rB, n);
  const e = approach < -1.2 ? restitution : 0;
  const jn = (-(1 + e) * un) / denom;
  const imp: V3 = [n[0] * jn, n[1] * jn, n[2] * jn];
  applyImpulse(A, rA, imp);
  if (B && rB) applyImpulse(B, rB, [-imp[0], -imp[1], -imp[2]]);
  // Friction on the post-impulse tangential velocity.
  const uA2 = pointVel(A, rA);
  const uB2 = B && rB ? pointVel(B, rB) : ([0, 0, 0] as V3);
  let t: V3 = [uA2[0] - uB2[0], uA2[1] - uB2[1], uA2[2] - uB2[2]];
  const tn = dot(t, n);
  t = [t[0] - n[0] * tn, t[1] - n[1] * tn, t[2] - n[2] * tn];
  const tl = Math.hypot(t[0], t[1], t[2]);
  if (tl > 1e-6) {
    const td: V3 = [t[0] / tl, t[1] / tl, t[2] / tl];
    let dt = 1 + angularTerm(rA, td);
    if (B && rB) dt += 1 + angularTerm(rB, td);
    const jt = Math.min(tl / dt, mu * jn);
    const fi: V3 = [-td[0] * jt, -td[1] * jt, -td[2] * jt];
    applyImpulse(A, rA, fi);
    if (B && rB) applyImpulse(B, rB, [-fi[0], -fi[1], -fi[2]]);
  }
  return jn;
}

export type Contacts = { floor: boolean };

/** Which face is up, 1 to 6, and how flat it lies (1 = perfectly level). */
export function topFace(d: Die): { value: number; flat: number; axis: V3 } {
  const m = qMat(d.q);
  let best = -2;
  let value = 1;
  let axis: V3 = [0, 1, 0];
  for (const f of FACE_AXES) {
    const a: V3 = [m[f.axis] * f.sign, m[3 + f.axis] * f.sign, m[6 + f.axis] * f.sign];
    if (a[1] > best) {
      best = a[1];
      value = f.value;
      axis = a;
    }
  }
  return { value, flat: best, axis };
}

export function stepDice(world: DiceWorld, dt: number, opts: DiceOptions = DICE_DEFAULTS) {
  let rem = dt;
  while (rem > 1e-9) {
    const h = Math.min(STEP, rem);
    rem -= h;
    substep(world, h, opts);
  }
}

function substep(world: DiceWorld, h: number, o: DiceOptions) {
  const { dice, halfX, halfZ } = world;
  world.clock += h;
  const mats: number[][] = [];
  for (const d of dice) {
    if (d.held || d.asleep) {
      mats.push(qMat(d.q));
      continue;
    }
    d.v[1] -= o.gravity * h;
    // Light air drag.
    const drag = 1 - 0.05 * h;
    d.v[0] *= drag; d.v[1] *= drag; d.v[2] *= drag;
    d.p[0] += d.v[0] * h;
    d.p[1] += d.v[1] * h;
    d.p[2] += d.v[2] * h;
    const wl = Math.hypot(d.w[0], d.w[1], d.w[2]);
    if (wl > 1e-9) {
      const dq = qAxisAngle(d.w, wl * h);
      d.q = qNorm(qMul(dq, d.q));
    }
    mats.push(qMat(d.q));
  }
  const grounded = dice.map(() => false);
  for (let iter = 0; iter < 4; iter++) {
    for (let i = 0; i < dice.length; i++) {
      const d = dice[i];
      if (d.held || d.asleep) continue;
      const offs = cornerOffsets(mats[i]);
      for (let c = 0; c < 8; c++) {
        const r = offs[c];
        const px = d.p[0] + r[0], py = d.p[1] + r[1], pz = d.p[2] + r[2];
        if (py < 0) {
          const approach = pointVel(d, r)[1];
          world.impact = Math.max(world.impact, resolveContact(d, r, null, null, [0, 1, 0], o.floorRestitution, o.floorFriction, approach));
          d.p[1] -= py * 0.5;
          grounded[i] = true;
        }
        if (px < -halfX) {
          const approach = pointVel(d, r)[0];
          world.impact = Math.max(world.impact, resolveContact(d, r, null, null, [1, 0, 0], o.wallRestitution, o.wallFriction, approach));
          d.p[0] += (-halfX - px) * 0.5;
        } else if (px > halfX) {
          const approach = -pointVel(d, r)[0];
          world.impact = Math.max(world.impact, resolveContact(d, r, null, null, [-1, 0, 0], o.wallRestitution, o.wallFriction, approach));
          d.p[0] -= (px - halfX) * 0.5;
        }
        if (pz < -halfZ) {
          const approach = pointVel(d, r)[2];
          world.impact = Math.max(world.impact, resolveContact(d, r, null, null, [0, 0, 1], o.wallRestitution, o.wallFriction, approach));
          d.p[2] += (-halfZ - pz) * 0.5;
        } else if (pz > halfZ) {
          const approach = -pointVel(d, r)[2];
          world.impact = Math.max(world.impact, resolveContact(d, r, null, null, [0, 0, -1], o.wallRestitution, o.wallFriction, approach));
          d.p[2] -= (pz - halfZ) * 0.5;
        }
      }
    }
    // Dice against dice: corners of one inside the other.
    for (let i = 0; i < dice.length; i++) {
      for (let j = i + 1; j < dice.length; j++) {
        const A = dice[i], B = dice[j];
        if (A.held || B.held) continue;
        const dx = B.p[0] - A.p[0], dy = B.p[1] - A.p[1], dz = B.p[2] - A.p[2];
        if (dx * dx + dy * dy + dz * dz > 3.1) continue;
        if (dieDie(A, mats[i], B, mats[j], o) | dieDie(B, mats[j], A, mats[i], o)) { grounded[i] = true; grounded[j] = true; }
      }
    }
  }
  // Rolling resistance and sleep.
  for (let i = 0; i < dice.length; i++) {
    const d = dice[i];
    if (d.held || d.asleep) continue;
    if (grounded[i]) {
      const k = 1 - o.rolling * h;
      d.w[0] *= k; d.w[1] *= 1 - o.rolling * 1.6 * h; d.w[2] *= k;
      d.v[0] *= 1 - 0.35 * h; d.v[2] *= 1 - 0.35 * h;
    }
    const sp = Math.hypot(d.v[0], d.v[1], d.v[2]);
    const sw = Math.hypot(d.w[0], d.w[1], d.w[2]);
    if (grounded[i] && sp < 0.35 && sw < 0.9) {
      d.rest += h;
      const tf = topFace(d);
      if (tf.flat < 0.9995 && d.rest > 0.08) {
        // A cube cannot stay balanced on an edge: gently tip it toward the nearest flat face.
        const t = cross(tf.axis, [0, 1, 0]);
        const g = 45 * h; d.w[0] += t[0] * g; d.w[1] += t[1] * g; d.w[2] += t[2] * g;
      } else if (d.rest > 0.22 && !overlapsOther(dice, i)) {
        d.asleep = true;
        d.v = [0, 0, 0];
        d.w = [0, 0, 0];
        d.p[1] = 0.5;
        // Align exactly flat so it does not creep.
        const m = qMat(d.q);
        void m;
      }
    } else {
      d.rest = 0;
    }
  }
  // Wake a sleeper that gets hit.
  for (let i = 0; i < dice.length; i++) {
    if (!dice[i].asleep) continue;
    for (let j = 0; j < dice.length; j++) {
      if (i === j || dice[j].asleep || dice[j].held) continue;
      const dx = dice[j].p[0] - dice[i].p[0], dy = dice[j].p[1] - dice[i].p[1], dz = dice[j].p[2] - dice[i].p[2];
      if (dx * dx + dy * dy + dz * dz < 1.9 && Math.hypot(dice[j].v[0], dice[j].v[1], dice[j].v[2]) > 1.2) dice[i].asleep = false;
    }
  }
  world.settledFor = dice.every((d) => d.asleep || d.held) ? world.settledFor + h : 0;
}

function overlapsOther(dice: Die[], i: number): boolean {
  for (let j = 0; j < dice.length; j++) {
    if (j === i) continue;
    const dx = dice[j].p[0] - dice[i].p[0], dy = dice[j].p[1] - dice[i].p[1], dz = dice[j].p[2] - dice[i].p[2];
    if (Math.abs(dy) < 0.9 && Math.hypot(dx, dz) < 0.97) return true;
  }
  return false;
}

function dieDie(A: Die, mA: number[], B: Die, mB: number[], o: DiceOptions): number {
  const offs = cornerOffsets(mA);
  let deepest = 0;
  let dn: V3 | null = null;
  const lcY = mB[1] * (A.p[0] - B.p[0]) + mB[4] * (A.p[1] - B.p[1]) + mB[7] * (A.p[2] - B.p[2]);
  {
    // Centre of A inside B (corner tests alone miss near-coincident cubes): shove them apart.
    const cw: V3 = [A.p[0] - B.p[0], A.p[1] - B.p[1], A.p[2] - B.p[2]];
    const lc: V3 = [
      mB[0] * cw[0] + mB[3] * cw[1] + mB[6] * cw[2],
      mB[1] * cw[0] + mB[4] * cw[1] + mB[7] * cw[2],
      mB[2] * cw[0] + mB[5] * cw[1] + mB[8] * cw[2],
    ];
    if (Math.abs(lc[0]) < 0.5 && Math.abs(lc[1]) < 0.5 && Math.abs(lc[2]) < 0.5) {
      // Prefer separating sideways: dice on the felt cannot go down.
      let k = 0, dk = 1 - Math.abs(lc[0]);
      for (let a = 1; a < 3; a++) {
        const d2 = 1 - Math.abs(lc[a]) + (a === 1 ? 0.6 : 0);
        if (d2 < dk) { dk = d2; k = a; }
      }
      const sg = lc[k] >= 0 ? 1 : -1;
      deepest = 1 - Math.abs(lc[k]);
      dn = [mB[k] * sg, mB[3 + k] * sg, mB[6 + k] * sg];
      A.asleep = false; B.asleep = false; A.rest = 0; B.rest = 0;
    }
  }
  for (let c = 0; c < 8; c++) {
    const r = offs[c];
    const wp: V3 = [A.p[0] + r[0] - B.p[0], A.p[1] + r[1] - B.p[1], A.p[2] + r[2] - B.p[2]];
    // Into B's local frame (transpose of its rotation).
    const l: V3 = [
      mB[0] * wp[0] + mB[3] * wp[1] + mB[6] * wp[2],
      mB[1] * wp[0] + mB[4] * wp[1] + mB[7] * wp[2],
      mB[2] * wp[0] + mB[5] * wp[1] + mB[8] * wp[2],
    ];
    const ax = Math.abs(l[0]), ay = Math.abs(l[1]), az = Math.abs(l[2]);
    const H = 0.5 + SKIN;
    if (ax >= H || ay >= H || az >= H) continue;
    let k = 0;
    let depth = H - ax;
    if (H - az < depth) { k = 2; depth = H - az; }
    // Vertical separation only when A's centre really is above or below B (stacking);
    // two dice side by side on the felt share a height and must slide apart sideways.
    if (Math.abs(lcY) > 0.62 && H - ay < depth) { k = 1; depth = H - ay; }
    const s = l[k] >= 0 ? 1 : -1;
    const n: V3 = [mB[k] * s, mB[3 + k] * s, mB[6 + k] * s];
    const rB: V3 = [wp[0], wp[1], wp[2]];
    const approach = dot(
      [pointVel(A, r)[0] - pointVel(B, rB)[0], pointVel(A, r)[1] - pointVel(B, rB)[1], pointVel(A, r)[2] - pointVel(B, rB)[2]],
      n,
    );
    resolveContact(A, r, B, rB, n, o.dieRestitution, o.dieFriction, approach);
    if (depth - SKIN > deepest) { deepest = depth - SKIN; dn = n; }
    if (approach < -0.6) {
      // A real knock wakes a sleeping die; gentle touching does not.
      A.asleep = false;
      B.asleep = false;
      A.rest = 0;
      B.rest = 0;
    }
  }
  if (dn) {
    // Separate along the deepest contact once, so overlapped dice never sleep inside each other.
    if (deepest > 0.06) { A.asleep = false; B.asleep = false; A.rest = 0; B.rest = 0; }
    const push = deepest * 0.5;
    A.p[0] += dn[0] * push; A.p[1] += dn[1] * push; A.p[2] += dn[2] * push;
    B.p[0] -= dn[0] * push; B.p[1] -= dn[1] * push; B.p[2] -= dn[2] * push;
    return 1;
  }
  return 0;
}

export function diceValues(world: DiceWorld): number[] {
  return world.dice.map((d) => topFace(d).value);
}

export function allSettled(world: DiceWorld): boolean {
  return world.dice.every((d) => d.asleep) && world.settledFor > 0.15;
}

export function kineticEnergy(world: DiceWorld): number {
  let e = 0;
  for (const d of world.dice) {
    e += 0.5 * (d.v[0] ** 2 + d.v[1] ** 2 + d.v[2] ** 2) + 0.5 * (1 / INV_I) * (d.w[0] ** 2 + d.w[1] ** 2 + d.w[2] ** 2);
  }
  return e;
}

/* ---------- picking up and throwing ---------- */

/** Lift every die into the hand. The caller then moves them with moveHeld. */
export function grabDice(world: DiceWorld, seed = 1) {
  const rng = mulberry(seed);
  for (const d of world.dice) {
    d.held = true;
    d.asleep = false;
    d.rest = 0;
    d.v = [0, 0, 0];
    d.w = [(rng() - 0.5) * 9, (rng() - 0.5) * 9, (rng() - 0.5) * 9];
  }
}

/** Carry the held dice toward a hand position; measures the hand velocity for the throw. */
export function moveHeld(world: DiceWorld, target: V3, dt: number) {
  const n = world.dice.length;
  world.dice.forEach((d, i) => {
    if (!d.held) return;
    const off = (i - (n - 1) / 2) * 1.15;
    const want: V3 = [
      Math.max(-world.halfX + 0.8, Math.min(world.halfX - 0.8, target[0] + off)),
      target[1],
      Math.max(-world.halfZ + 0.8, Math.min(world.halfZ - 0.8, target[2])),
    ];
    const k = Math.min(1, dt * 16);
    const nx = d.p[0] + (want[0] - d.p[0]) * k;
    const ny = d.p[1] + (want[1] - d.p[1]) * k;
    const nz = d.p[2] + (want[2] - d.p[2]) * k;
    const inv = dt > 1e-6 ? 1 / dt : 0;
    // Smoothed hand velocity.
    d.v = [
      d.v[0] * 0.7 + ((nx - d.p[0]) * inv) * 0.3,
      d.v[1] * 0.7 + ((ny - d.p[1]) * inv) * 0.3,
      d.v[2] * 0.7 + ((nz - d.p[2]) * inv) * 0.3,
    ];
    d.p = [nx, ny, nz];
    const wl = Math.hypot(d.w[0], d.w[1], d.w[2]);
    if (wl > 1e-9) d.q = qNorm(qMul(qAxisAngle(d.w, wl * dt), d.q));
  });
}

/** Let go: each die leaves with the hand velocity plus a flick of spin. Returns the launch speed. */
export function releaseDice(world: DiceWorld, seed = 1): number {
  const rng = mulberry(seed);
  let speed = 0;
  for (const d of world.dice) {
    if (!d.held) continue;
    d.held = false;
    d.asleep = false;
    d.rest = 0;
    let vx = d.v[0], vy = d.v[1], vz = d.v[2];
    const l = Math.hypot(vx, vy, vz);
    const cap = 42;
    if (l > cap) { vx *= cap / l; vy *= cap / l; vz *= cap / l; }
    d.v = [vx, vy, vz];
    speed = Math.max(speed, Math.hypot(vx, vz));
    const sp = 10 + Math.hypot(vx, vz) * 0.7;
    d.w = [vz * 0.55 + (rng() - 0.5) * sp * 0.5, (rng() - 0.5) * sp * 0.5, -vx * 0.55 + (rng() - 0.5) * sp * 0.5];
  }
  world.settledFor = 0;
  return speed;
}

/* Camera, lighting and the draw list for the dice tray. Pure TypeScript: the
   same list is painted by the Skia component and by the web Canvas2D preview. */
import { FACE_AXES, qMat, type DiceWorld, type Die, type V3 } from "./diceMath";

export const TRAY_W = 340;
export const TRAY_H = 460;

export type Item =
  | { k: "poly"; pts: number[]; color: string; alpha?: number; blur?: number; grad?: { x0: number; y0: number; x1: number; y1: number; c0: string; c1: string } }
  | { k: "dots"; pts: number[]; color: string; size: number; alpha: number }
  | { k: "line"; pts: number[]; color: string; width: number; alpha?: number };

/* ---------- camera ---------- */
const EYE: V3 = [0, 11.6, 9.4];
const TARGET: V3 = [0, 0, 0.1];
const FOCAL = 500;
const CX = TRAY_W / 2;
const CY = TRAY_H * 0.47;

function norm(a: V3): V3 {
  const l = Math.hypot(a[0], a[1], a[2]) || 1;
  return [a[0] / l, a[1] / l, a[2] / l];
}
const sub = (a: V3, b: V3): V3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const dotv = (a: V3, b: V3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const crossv = (a: V3, b: V3): V3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];

const FWD = norm(sub(TARGET, EYE));
const RIGHT = norm(crossv(FWD, [0, 1, 0]));
const UPV = crossv(RIGHT, FWD);

export function project(p: V3): [number, number, number] {
  const d = sub(p, EYE);
  const z = dotv(d, FWD);
  const s = FOCAL / z;
  return [CX + dotv(d, RIGHT) * s, CY - dotv(d, UPV) * s, z];
}

/** The point on the horizontal plane y = planeY under a screen position. */
export function unproject(sx: number, sy: number, planeY: number): V3 {
  const dir = norm([
    FWD[0] + RIGHT[0] * ((sx - CX) / FOCAL) - UPV[0] * ((sy - CY) / FOCAL),
    FWD[1] + RIGHT[1] * ((sx - CX) / FOCAL) - UPV[1] * ((sy - CY) / FOCAL),
    FWD[2] + RIGHT[2] * ((sx - CX) / FOCAL) - UPV[2] * ((sy - CY) / FOCAL),
  ]);
  const t = (planeY - EYE[1]) / dir[1];
  return [EYE[0] + dir[0] * t, planeY, EYE[2] + dir[2] * t];
}

/** World units per pixel on the felt near the middle of the tray. */
export function worldPerPixel(): number {
  const a = unproject(CX, CY, 0);
  const b = unproject(CX + 1, CY, 0);
  return Math.abs(b[0] - a[0]);
}

/* ---------- light and colour ---------- */
const LIGHT: V3 = [-4.5, 13, 6];
const rgb = (r: number, g: number, b: number) =>
  `rgb(${Math.max(0, Math.min(255, Math.round(r)))},${Math.max(0, Math.min(255, Math.round(g)))},${Math.max(0, Math.min(255, Math.round(b)))})`;

type Rgb = [number, number, number];
const DIE_BASE: Rgb = [186, 22, 30];
const PIP_BASE: Rgb = [246, 240, 226];
const FELT_BOUNCE: Rgb = [22, 78, 46];

function lit(base: Rgb, p: V3, n: V3, gloss: number): Rgb {
  const l = norm(sub(LIGHT, p));
  const v = norm(sub(EYE, p));
  const h = norm([l[0] + v[0], l[1] + v[1], l[2] + v[2]]);
  const nl = Math.max(0, dotv(n, l));
  const sky = 0.5 + 0.5 * n[1];
  const diff = 0.2 + 0.82 * nl + 0.18 * sky;
  const spec = gloss * Math.pow(Math.max(0, dotv(n, h)), 64);
  const rim = gloss * 0.35 * Math.pow(1 - Math.max(0, dotv(n, v)), 3) * sky;
  const bounce = Math.max(0, -n[1]) * 0.55 + 0.1 * (1 - Math.abs(n[1]));
  // A glossy red acrylic die lets some light through: lift the shadow side toward warm red.
  const glow = 0.11 * gloss;
  return [
    base[0] * (diff + glow) + FELT_BOUNCE[0] * bounce + 255 * (spec + rim * 0.5),
    base[1] * (diff + glow * 0.4) + FELT_BOUNCE[1] * bounce + 255 * (spec + rim * 0.5),
    base[2] * (diff + glow * 0.4) + FELT_BOUNCE[2] * bounce + 255 * (spec + rim * 0.5),
  ];
}

/* ---------- felt, rails (static) ---------- */
function mulberry(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function quad(a: V3, b: V3, c: V3, d: V3, color: string, extra: Partial<Item> = {}): Item {
  const pa = project(a), pb = project(b), pc = project(c), pd = project(d);
  return { k: "poly", pts: [pa[0], pa[1], pb[0], pb[1], pc[0], pc[1], pd[0], pd[1]], color, ...extra } as Item;
}

const RAIL_H = 0.7;
const RAIL_W = 1.1;

export function staticScene(halfX: number, halfZ: number): { back: Item[]; front: Item[] } {
  const back: Item[] = [];
  const front: Item[] = [];
  const ox = halfX + RAIL_W, oz = halfZ + RAIL_W;
  // Table surface outside the tray.
  back.push({ k: "poly", pts: [0, 0, TRAY_W, 0, TRAY_W, TRAY_H, 0, TRAY_H], color: "rgb(26,18,13)" });
  // Rail tops (padded leather) behind the felt: far rail, left, right.
  const topY = RAIL_H;
  const leatherA = "rgb(70,44,30)";
  const leatherB = "rgb(40,24,16)";
  const rail = (a: V3, b: V3, c: V3, d: V3, c0 = leatherA, c1 = leatherB) => {
    const pa = project(a), pc = project(c);
    return quad(a, b, c, d, c0, { grad: { x0: pa[0], y0: pa[1], x1: pc[0], y1: pc[1], c0, c1 } });
  };
  back.push(rail([-ox, topY, -oz], [ox, topY, -oz], [ox, topY, -halfZ], [-ox, topY, -halfZ]));
  back.push(rail([-ox, topY, -oz], [-halfX, topY, -oz], [-halfX, topY, oz], [-ox, topY, oz]));
  back.push(rail([halfX, topY, -oz], [ox, topY, -oz], [ox, topY, oz], [halfX, topY, oz]));
  // Inner walls (felt-covered): far wall and the two sides.
  const wallFar0 = "rgb(30,92,58)", wallFar1 = "rgb(14,50,31)";
  const wf = [project([-halfX, topY, -halfZ]), project([halfX, topY, -halfZ])];
  back.push(quad([-halfX, 0, -halfZ], [halfX, 0, -halfZ], [halfX, topY, -halfZ], [-halfX, topY, -halfZ], wallFar0, { grad: { x0: 0, y0: project([0, 0, -halfZ])[1], x1: 0, y1: wf[0][1], c0: wallFar1, c1: wallFar0 } }));
  const wl = project([-halfX, 0, 0]), wl2 = project([-halfX, 0, -halfZ]);
  back.push(quad([-halfX, 0, -halfZ], [-halfX, 0, halfZ], [-halfX, topY, halfZ], [-halfX, topY, -halfZ], "rgb(22,70,43)", { grad: { x0: wl[0], y0: wl[1], x1: wl2[0], y1: wl2[1], c0: "rgb(25,80,49)", c1: "rgb(14,46,29)" } }));
  back.push(quad([halfX, 0, -halfZ], [halfX, 0, halfZ], [halfX, topY, halfZ], [halfX, topY, -halfZ], "rgb(18,58,36)", { grad: { x0: project([halfX, 0, 0])[0], y0: wl[1], x1: project([halfX, 0, -halfZ])[0], y1: wl2[1], c0: "rgb(20,64,40)", c1: "rgb(11,38,24)" } }));
  // Felt floor.
  const f0 = project([-halfX, 0, -halfZ]), f1 = project([halfX, 0, -halfZ]), f2 = project([halfX, 0, halfZ]), f3 = project([-halfX, 0, halfZ]);
  back.push({ k: "poly", pts: [f0[0], f0[1], f1[0], f1[1], f2[0], f2[1], f3[0], f3[1]], color: "rgb(31,98,60)", grad: { x0: 0, y0: f0[1], x1: 0, y1: f3[1], c0: "rgb(27,84,52)", c1: "rgb(36,112,69)" } });
  // Soft pool of light on the felt: stacked rings fake a blur on every renderer.
  for (let ring = 0; ring < 9; ring++) {
    const k = 1 - ring * 0.1;
    const lp: number[] = [];
    for (let i = 0; i < 32; i++) {
      const t = (i / 32) * Math.PI * 2;
      const p = project([-0.5 + Math.cos(t) * halfX * 0.95 * k, 0, 0.4 + Math.sin(t) * halfZ * 0.85 * k]);
      lp.push(p[0], p[1]);
    }
    back.push({ k: "poly", pts: lp, color: "rgb(130,220,160)", alpha: 0.035 });
  }
  // Felt nap: thousands of fibre specks in felt plane coordinates, projected.
  const rng = mulberry(77);
  const dark: number[] = [], light: number[] = [], mid: number[] = [];
  for (let i = 0; i < 4200; i++) {
    const p = project([(rng() * 2 - 1) * halfX, 0, (rng() * 2 - 1) * halfZ]);
    const r = rng();
    (r < 0.4 ? dark : r < 0.75 ? light : mid).push(p[0], p[1]);
  }
  back.push({ k: "dots", pts: dark, color: "rgb(8,40,22)", size: 1.1, alpha: 0.34 });
  back.push({ k: "dots", pts: light, color: "rgb(120,200,150)", size: 1.0, alpha: 0.2 });
  back.push({ k: "dots", pts: mid, color: "rgb(60,140,90)", size: 1.4, alpha: 0.16 });
  // Contact shadow where the wall meets the felt.
  const far = project([0, 0, -halfZ]);
  back.push({ k: "line", pts: [f0[0], far[1], f1[0], far[1]], color: "rgb(0,0,0)", width: 7, alpha: 0.35 });
  // Near rail top, in front of the dice.
  front.push(rail([-ox, topY, halfZ], [ox, topY, halfZ], [ox, topY, oz], [-ox, topY, oz], "rgb(78,50,34)", "rgb(54,34,22)"));
  // Light catching the rounded inner edge of the padding.
  const e0 = project([-halfX, topY, halfZ]), e1 = project([halfX, topY, halfZ]);
  front.push({ k: "line", pts: [e0[0], e0[1], e1[0], e1[1]], color: "rgb(150,104,72)", width: 2, alpha: 0.7 });
  const g0 = project([-halfX, topY, -halfZ]), g1 = project([halfX, topY, -halfZ]);
  back.push({ k: "line", pts: [g0[0], g0[1], g1[0], g1[1]], color: "rgb(150,104,72)", width: 2, alpha: 0.5 });
  return { back, front };
}

/* ---------- dice ---------- */
const BEVEL = 0.085;
const PIP_G = 0.235;
const PIP_R = 0.092;
const PIP_LAYOUT: Record<number, [number, number][]> = {
  1: [[0, 0]],
  2: [[-1, -1], [1, 1]],
  3: [[-1, -1], [0, 0], [1, 1]],
  4: [[-1, -1], [1, -1], [-1, 1], [1, 1]],
  5: [[-1, -1], [1, -1], [0, 0], [-1, 1], [1, 1]],
  6: [[-1, -1], [-1, 0], [-1, 1], [1, -1], [1, 0], [1, 1]],
};

function hull(points: number[][]): number[][] {
  const p = points.slice().sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const cr = (o: number[], a: number[], b: number[]) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const lo: number[][] = [];
  for (const q of p) { while (lo.length >= 2 && cr(lo[lo.length - 2], lo[lo.length - 1], q) <= 0) lo.pop(); lo.push(q); }
  const up: number[][] = [];
  for (let i = p.length - 1; i >= 0; i--) { const q = p[i]; while (up.length >= 2 && cr(up[up.length - 2], up[up.length - 1], q) <= 0) up.pop(); up.push(q); }
  lo.pop(); up.pop();
  return lo.concat(up);
}

const DIE_LIGHT_DIR: V3 = norm([-0.38, -1, -0.5]);

function shadowItems(d: Die, m: number[], out: Item[]) {
  const worldPts: V3[] = [];
  for (let i = 0; i < 8; i++) {
    const c: V3 = [i & 1 ? 0.5 : -0.5, i & 2 ? 0.5 : -0.5, i & 4 ? 0.5 : -0.5];
    worldPts.push([
      d.p[0] + m[0] * c[0] + m[1] * c[1] + m[2] * c[2],
      d.p[1] + m[3] * c[0] + m[4] * c[1] + m[5] * c[2],
      d.p[2] + m[6] * c[0] + m[7] * c[1] + m[8] * c[2],
    ]);
  }
  const height = Math.max(0, d.p[1] - 0.5);
  // Directional shadow, longer and softer as the die rises.
  const cast = worldPts.map((p) => {
    const t = Math.max(0, p[1]) / -DIE_LIGHT_DIR[1];
    const q = project([p[0] + DIE_LIGHT_DIR[0] * t, 0.004, p[2] + DIE_LIGHT_DIR[2] * t]);
    return [q[0], q[1]];
  });
  const h1 = hull(cast).flat();
  const soft = 3 + height * 7;
  out.push({ k: "poly", pts: h1, color: "rgb(2,12,6)", alpha: Math.max(0.18, 0.42 - height * 0.08), blur: soft });
  // Red light bleeding off the acrylic onto the felt.
  out.push({ k: "poly", pts: hull(worldPts.map((p) => { const q = project([d.p[0] + (p[0] - d.p[0]) * 1.25, 0.002, d.p[2] + (p[2] - d.p[2]) * 1.25]); return [q[0], q[1]]; })).flat(), color: "rgb(170,26,34)", alpha: 0.14 * Math.max(0, 1 - height / 1.4), blur: 7 });
  // Ambient occlusion: tight dark contact under the die, fading quickly with height.
  const under = worldPts.map((p) => {
    const q = project([d.p[0] + (p[0] - d.p[0]) * 1.06, 0.003, d.p[2] + (p[2] - d.p[2]) * 1.06]);
    return [q[0], q[1]];
  });
  const ao = Math.max(0, 1 - height / 1.3);
  if (ao > 0.01) out.push({ k: "poly", pts: hull(under).flat(), color: "rgb(0,6,3)", alpha: 0.55 * ao, blur: 2.2 + height * 4 });
}

type Facet = { verts: V3[]; n: V3 };

function dieFacets(d: Die, m: number[]): { facets: Facet[]; pips: { c: V3; u: V3; v: V3; n: V3; r: number }[] } {
  const rot = (l: V3): V3 => [
    d.p[0] + m[0] * l[0] + m[1] * l[1] + m[2] * l[2],
    d.p[1] + m[3] * l[0] + m[4] * l[1] + m[5] * l[2],
    d.p[2] + m[6] * l[0] + m[7] * l[1] + m[8] * l[2],
  ];
  const rotN = (l: V3): V3 => [m[0] * l[0] + m[1] * l[1] + m[2] * l[2], m[3] * l[0] + m[4] * l[1] + m[5] * l[2], m[6] * l[0] + m[7] * l[1] + m[8] * l[2]];
  const facets: Facet[] = [];
  const pips: { c: V3; u: V3; v: V3; n: V3; r: number }[] = [];
  const H = 0.5, I = 0.5 - BEVEL;
  const mk = (xs: number[]): V3 => [xs[0], xs[1], xs[2]];
  // Faces.
  for (const f of FACE_AXES) {
    const a = f.axis, ta = (a + 1) % 3, tb = (a + 2) % 3;
    const corner = (su: number, sv: number): V3 => {
      const v = [0, 0, 0];
      v[a] = f.sign * H; v[ta] = su * I; v[tb] = sv * I;
      return rot(mk(v));
    };
    const nl = [0, 0, 0]; nl[a] = f.sign;
    facets.push({ verts: [corner(-1, -1), corner(1, -1), corner(1, 1), corner(-1, 1)], n: rotN(mk(nl)) });
    const ul = [0, 0, 0]; ul[ta] = 1;
    const vl = [0, 0, 0]; vl[tb] = 1;
    for (const [pu, pv] of PIP_LAYOUT[f.value]) {
      const cl = [0, 0, 0]; cl[a] = f.sign * H; cl[ta] = pu * PIP_G; cl[tb] = pv * PIP_G;
      pips.push({ c: rot(mk(cl)), u: rotN(mk(ul)), v: rotN(mk(vl)), n: rotN(mk(nl)), r: PIP_R });
    }
  }
  // Edge bevels: 12 strips between neighbouring faces.
  for (let a = 0; a < 3; a++) {
    const b = (a + 1) % 3, c = (a + 2) % 3;
    for (const sa of [1, -1]) for (const sb of [1, -1]) {
      const p1 = (t: number) => { const v = [0, 0, 0]; v[a] = sa * H; v[b] = sb * I; v[c] = t; return rot(mk(v)); };
      const p2 = (t: number) => { const v = [0, 0, 0]; v[a] = sa * I; v[b] = sb * H; v[c] = t; return rot(mk(v)); };
      const nl = [0, 0, 0]; nl[a] = sa; nl[b] = sb;
      facets.push({ verts: [p1(-I), p1(I), p2(I), p2(-I)], n: rotN(norm(mk(nl))) });
    }
  }
  // Corner triangles.
  for (const sx of [1, -1]) for (const sy of [1, -1]) for (const sz of [1, -1]) {
    const va = rot([sx * H, sy * I, sz * I]), vb = rot([sx * I, sy * H, sz * I]), vc = rot([sx * I, sy * I, sz * H]);
    facets.push({ verts: sx * sy * sz > 0 ? [va, vb, vc] : [va, vc, vb], n: rotN(norm([sx, sy, sz])) });
  }
  return { facets, pips };
}

function dieItems(d: Die, out: Item[]) {
  const m = qMat(d.q);
  const { facets, pips } = dieFacets(d, m);
  const centre = d.p;
  const view = (p: V3) => norm(sub(EYE, p));
  // Painter's order inside one convex die: far facets first is unnecessary after culling.
  for (const f of facets) {
    const mid: V3 = [0, 0, 0];
    for (const v of f.verts) { mid[0] += v[0] / f.verts.length; mid[1] += v[1] / f.verts.length; mid[2] += v[2] / f.verts.length; }
    if (dotv(f.n, view(mid)) <= 0.0) continue;
    const pts: number[] = [];
    for (const v of f.verts) { const p = project(v); pts.push(p[0], p[1]); }
    const c0 = lit(DIE_BASE, f.verts[0], f.n, 1);
    const mc = lit(DIE_BASE, f.verts[Math.floor(f.verts.length / 2)], f.n, 1);
    out.push({
      k: "poly", pts, color: rgb(mc[0], mc[1], mc[2]),
      grad: f.verts.length === 4
        ? { x0: pts[0], y0: pts[1], x1: pts[4], y1: pts[5], c0: rgb(c0[0], c0[1], c0[2]), c1: rgb(mc[0], mc[1], mc[2]) }
        : undefined,
    });
  }
  // Softbox reflection on the glossy faces: a blurred white window that slides across as the die turns.
  for (let fi = 0; fi < 6; fi++) {
    const f = facets[fi];
    const mid: V3 = [(f.verts[0][0] + f.verts[2][0]) / 2, (f.verts[0][1] + f.verts[2][1]) / 2, (f.verts[0][2] + f.verts[2][2]) / 2];
    const vv = view(mid);
    if (dotv(f.n, vv) <= 0.05) continue;
    const l = norm(sub(LIGHT, mid));
    const hv = norm([l[0] + vv[0], l[1] + vv[1], l[2] + vv[2]]);
    const nh = Math.max(0, dotv(f.n, hv));
    const a = Math.pow(nh, 18) * 0.62;
    if (a < 0.03) continue;
    // Window slides across the face with the half-vector offset.
    const e1: V3 = norm(sub(f.verts[1], f.verts[0]));
    const e2: V3 = norm(sub(f.verts[3], f.verts[0]));
    const ox = Math.max(-0.5, Math.min(0.5, dotv(sub(hv, f.n), e1) * 3.2));
    const oy = Math.max(-0.5, Math.min(0.5, dotv(sub(hv, f.n), e2) * 3.2));
    const cx = mid[0] + e1[0] * ox * 0.5 + e2[0] * oy * 0.5;
    const cy = mid[1] + e1[1] * ox * 0.5 + e2[1] * oy * 0.5;
    const cz = mid[2] + e1[2] * ox * 0.5 + e2[2] * oy * 0.5;
    const hw = 0.22, hh = 0.1;
    const corner = (su: number, sv: number): number[] => {
      const q = project([cx + e1[0] * su * hw + e2[0] * sv * hh, cy + e1[1] * su * hw + e2[1] * sv * hh, cz + e1[2] * su * hw + e2[2] * sv * hh]);
      return [q[0], q[1]];
    };
    const c = [corner(-1, -1), corner(1, -1), corner(1, 1), corner(-1, 1)].flat();
    out.push({ k: "poly", pts: c, color: "rgb(255,236,230)", alpha: Math.min(0.75, a), blur: 2.4 });
  }
  // Pips on visible faces.
  for (const p of pips) {
    if (dotv(p.n, view(p.c)) <= 0.04) continue;
    const toLight = norm(sub(LIGHT, p.c));
    // The rim facing the light is in shadow, the opposite rim catches light.
    const lu = dotv(toLight, p.u), lv = dotv(toLight, p.v);
    const ll = Math.hypot(lu, lv) || 1;
    const sh = 0.016;
    const ring = (r: number, ox: number, oy: number, depth: number): number[] => {
      const pts: number[] = [];
      for (let i = 0; i < 20; i++) {
        const t = (i / 20) * Math.PI * 2;
        const x = Math.cos(t) * r + ox, y = Math.sin(t) * r + oy;
        const q = project([
          p.c[0] + p.u[0] * x + p.v[0] * y - p.n[0] * depth,
          p.c[1] + p.u[1] * x + p.v[1] * y - p.n[1] * depth,
          p.c[2] + p.u[2] * x + p.v[2] * y - p.n[2] * depth,
        ]);
        pts.push(q[0], q[1]);
      }
      return pts;
    };
    // Drilled recess: dark wall, then the painted pip sunk a little.
    out.push({ k: "poly", pts: ring(p.r * 1.1, 0, 0, 0), color: "rgb(70,6,10)", alpha: 0.9 });
    const pc = lit(PIP_BASE, p.c, p.n, 0.8);
    const pcDark: Rgb = [pc[0] * 0.78, pc[1] * 0.76, pc[2] * 0.74];
    const a0 = ring(p.r, lu / ll * sh, lv / ll * sh, 0.012);
    out.push({
      k: "poly", pts: a0, color: rgb(pc[0], pc[1], pc[2]),
      grad: (() => {
        const q0 = project([p.c[0] + p.u[0] * (-lu / ll) * p.r + p.v[0] * (-lv / ll) * p.r, p.c[1] + p.u[1] * (-lu / ll) * p.r + p.v[1] * (-lv / ll) * p.r, p.c[2] + p.u[2] * (-lu / ll) * p.r + p.v[2] * (-lv / ll) * p.r]);
        const q1 = project([p.c[0] + p.u[0] * (lu / ll) * p.r + p.v[0] * (lv / ll) * p.r, p.c[1] + p.u[1] * (lu / ll) * p.r + p.v[1] * (lv / ll) * p.r, p.c[2] + p.u[2] * (lu / ll) * p.r + p.v[2] * (lv / ll) * p.r]);
        return { x0: q0[0], y0: q0[1], x1: q1[0], y1: q1[1], c0: rgb(pcDark[0], pcDark[1], pcDark[2]), c1: rgb(pc[0], pc[1], pc[2]) };
      })(),
    });
  }
  void centre;
}

export function buildFrame(world: DiceWorld, held?: boolean): { shadows: Item[]; dice: Item[] } {
  const shadows: Item[] = [];
  const dice: Item[] = [];
  void held;
  const order = world.dice
    .map((d, i) => ({ d, z: project(d.p)[2], i }))
    .sort((a, b) => b.z - a.z);
  for (const { d } of order) shadowItems(d, qMat(d.q), shadows);
  for (const { d } of order) dieItems(d, dice);
  return { shadows, dice };
}

import React, { useState } from "react";
import { Pressable, Text, View } from "react-native";
import { DiceTray } from "./DiceTray";

export default function Example({
  onFeedback,
}: {
  onFeedback?: (event: "pickup" | "throw" | "impact" | "settle", strength?: number) => void;
}) {
  const [slow, setSlow] = useState(false);
  const [reduce, setReduce] = useState(false);
  const [count, setCount] = useState<1 | 2 | 3>(2);
  const [rollTick, setRollTick] = useState(0);
  const [values, setValues] = useState<number[] | null>(null);
  const chip = (on: boolean) => ({
    paddingVertical: 9, paddingHorizontal: 13, borderRadius: 24, borderWidth: 1,
    backgroundColor: on ? "#315843" : "#eeeade", borderColor: on ? "#315843" : "#c7caba",
  });
  const total = values ? values.reduce((a, b) => a + b, 0) : 0;
  return (
    <View style={{ alignItems: "center", gap: 10, paddingVertical: 14 }}>
      <DiceTray
        count={count}
        slowMotion={slow}
        reducedMotion={reduce}
        rollTick={rollTick}
        onSettled={setValues}
        onFeedback={(e, s) => {
          if (e === "pickup" || e === "throw") setValues(null);
          onFeedback?.(e, s);
        }}
      />
      <Text accessibilityLiveRegion="polite" style={{ fontSize: 15, color: "#1f3a2a", fontFamily: "Geist-Regular", minHeight: 20 }}>
        {values ? `${values.join(" + ")}${values.length > 1 ? ` = ${total}` : ""}` : "Drag to pick up, flick to throw"}
      </Text>
      <View style={{ flexDirection: "row", gap: 8, flexWrap: "wrap", justifyContent: "center" }}>
        <Pressable accessibilityRole="button" onPress={() => { setValues(null); setRollTick((v) => v + 1); }} style={chip(false)}>
          <Text style={{ fontSize: 12, color: "#315843", fontFamily: "Geist-Regular" }}>Roll</Text>
        </Pressable>
        {([1, 2, 3] as const).map((n) => (
          <Pressable key={n} accessibilityRole="button" accessibilityState={{ selected: count === n }} onPress={() => { setCount(n); setValues(null); }} style={chip(count === n)}>
            <Text style={{ fontSize: 12, color: count === n ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>{n} {n === 1 ? "die" : "dice"}</Text>
          </Pressable>
        ))}
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: slow }} onPress={() => setSlow((v) => !v)} style={chip(slow)}>
          <Text style={{ fontSize: 12, color: slow ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Slow motion: {slow ? "on" : "off"}</Text>
        </Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: reduce }} onPress={() => setReduce((v) => !v)} style={chip(reduce)}>
          <Text style={{ fontSize: 12, color: reduce ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Reduce motion: {reduce ? "on" : "off"}</Text>
        </Pressable>
      </View>
    </View>
  );
}
